 @page "/shipments"
 @attribute [Microsoft.AspNetCore.Authorization.Authorize]

 @inject IShipmentService ShipmentService

 <PageTitle>Shipments</PageTitle>

 <h1>Shipment Dashboard</h1>

 <div class="mb-3" style="max-width: 400px;">
     <input type="text" class="form-control" placeholder="Filter by tracking # or destination..."
            @bind="filterText" @bind:event="oninput" />
 </div>

 @if (shipments is null)
 {
     <p><em>Loading shipments...</em></p>
 }
 else if (!FilteredShipments.Any())
 {
     <p>No shipments match your filter.</p>
 }
 else
 {
     <div class="table-responsive">
         <table class="table table-striped table-hover">
             <thead>
                 <tr>
                     <th>Tracking #</th>
                     <th>Origin</th>
                     <th>Destination</th>
                     <th>Status</th>
                     <th>Shipped Date</th>
                     <th>Est. Delivery</th>
                     <th>Actions</th>
                 </tr>
             </thead>
             <tbody>
                 @foreach (var s in FilteredShipments)
                 {
                     <tr>
                         <td><a href="shipments/@s.Id">@s.TrackingNumber</a></td>
                         <td>@s.Origin</td>
                         <td>@s.Destination</td>
                         <td><span class="badge @GetStatusBadgeClass(s.Status)">@s.Status</span></td>
                         <td>@s.ShippedDate.ToString("MMM dd, yyyy")</td>
                         <td>@s.EstimatedDelivery.ToString("MMM dd, yyyy")</td>
                         <td>
                             <select class="form-select form-select-sm" style="width: auto; display: inline-block;"
                                     value="@((int)s.Status)"
                                     @onchange="(e) => UpdateStatus(s, e)">
                                 @foreach (ShipmentStatus status in Enum.GetValues<ShipmentStatus>())
                                 {
                                     <option value="@((int)status)">@status</option>
                                 }
                             </select>
                         </td>
                     </tr>
                 }
             </tbody>
         </table>
     </div>
 }

 @code {
     private List<Shipment>? shipments;
     private string filterText = string.Empty;

     private IEnumerable<Shipment> FilteredShipments =>
         shipments?.Where(s =>
             string.IsNullOrWhiteSpace(filterText) ||
             s.TrackingNumber.Contains(filterText, StringComparison.OrdinalIgnoreCase) ||
             s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase)
         ) ?? [];

     protected override async Task OnInitializedAsync()
     {
         shipments = await ShipmentService.GetAllShipmentsAsync();
     }

     private async Task UpdateStatus(Shipment shipment, ChangeEventArgs e)
     {
         if (int.TryParse(e.Value?.ToString(), out var statusInt))
         {
             var newStatus = (ShipmentStatus)statusInt;
             await ShipmentService.UpdateShipmentStatusAsync(shipment.Id, newStatus);
             shipment.Status = newStatus;
             if (newStatus == ShipmentStatus.Delivered && !shipment.ActualDelivery.HasValue)
                 shipment.ActualDelivery = DateTime.UtcNow;
         }
     }

     private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
     {
         ShipmentStatus.Delivered => "bg-success",
         ShipmentStatus.InTransit => "bg-primary",
         ShipmentStatus.OutForDelivery => "bg-info",
         ShipmentStatus.Delayed => "bg-danger",
         ShipmentStatus.PickedUp => "bg-secondary",
         _ => "bg-warning text-dark"
     };
 }

