 @page "/shipments/{Id:int}"
 @attribute [Microsoft.AspNetCore.Authorization.Authorize]

 @inject IShipmentService ShipmentService
 @inject NavigationManager Navigation

 <PageTitle>Shipment Details</PageTitle>

 @if (shipment is null)
 {
     <p><em>Loading shipment...</em></p>
 }
 else
 {
     <h1>Shipment @shipment.TrackingNumber</h1>

     <div class="card" style="max-width: 600px;">
         <div class="card-header d-flex justify-content-between align-items-center">
             <span><strong>@shipment.TrackingNumber</strong></span>
             <span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span>
         </div>
         <div class="card-body">
             <dl class="row mb-0">
                 <dt class="col-sm-5">Description</dt>
                 <dd class="col-sm-7">@shipment.Description</dd>

                 <dt class="col-sm-5">Origin</dt>
                 <dd class="col-sm-7">@shipment.Origin</dd>

                 <dt class="col-sm-5">Destination</dt>
                 <dd class="col-sm-7">@shipment.Destination</dd>

                 <dt class="col-sm-5">Customer Email</dt>
                 <dd class="col-sm-7">@shipment.CustomerEmail</dd>

                 <dt class="col-sm-5">Shipped Date</dt>
                 <dd class="col-sm-7">@shipment.ShippedDate.ToString("MMM dd, yyyy")</dd>

                 <dt class="col-sm-5">Estimated Delivery</dt>
                 <dd class="col-sm-7">@shipment.EstimatedDelivery.ToString("MMM dd, yyyy")</dd>

                 @if (shipment.ActualDelivery.HasValue)
                 {
                     <dt class="col-sm-5">Actual Delivery</dt>
                     <dd class="col-sm-7">@shipment.ActualDelivery.Value.ToString("MMM dd, yyyy")</dd>
                 }

                 <dt class="col-sm-5">Update Status</dt>
                 <dd class="col-sm-7">
                     <select class="form-select form-select-sm" style="width: auto;"
                             value="@((int)shipment.Status)"
                             @onchange="OnStatusChanged">
                         @foreach (ShipmentStatus status in Enum.GetValues<ShipmentStatus>())
                         {
                             <option value="@((int)status)">@status</option>
                         }
                     </select>
                 </dd>
             </dl>
         </div>
     </div>

     @if (statusUpdated)
     {
         <div class="alert alert-success mt-3" style="max-width: 600px;">Status updated successfully.</div>
     }

     <div class="mt-3">
         <a href="shipments" class="btn btn-outline-secondary">← Back to Shipments</a>
     </div>
 }

 @code {
     [Parameter] public int Id { get; set; }

     private Shipment? shipment;
     private bool statusUpdated;

     protected override async Task OnInitializedAsync()
     {
         shipment = await ShipmentService.GetShipmentByIdAsync(Id);
     }

     private async Task OnStatusChanged(ChangeEventArgs e)
     {
         if (shipment is null) return;
         if (int.TryParse(e.Value?.ToString(), out var statusInt))
         {
             var newStatus = (ShipmentStatus)statusInt;
             await ShipmentService.UpdateShipmentStatusAsync(shipment.Id, newStatus);
             shipment.Status = newStatus;
             if (newStatus == ShipmentStatus.Delivered && !shipment.ActualDelivery.HasValue)
                 shipment.ActualDelivery = DateTime.UtcNow;
             statusUpdated = true;
         }
     }

     private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
     {
         ShipmentStatus.Delivered => "bg-success",
         ShipmentStatus.InTransit => "bg-primary",
         ShipmentStatus.OutForDelivery => "bg-info",
         ShipmentStatus.Delayed => "bg-danger",
         ShipmentStatus.PickedUp => "bg-secondary",
         _ => "bg-warning text-dark"
     };
 }

